provenance={'kind':'original','author':'umi local content','sourceUrl':None,'license':None,'editorialReview':'pending'}
lessons=[]; words={}; exercises=[]
for row in DATA.strip().splitlines():
    parts=row.split('|')
    if row.startswith('@'):
        number=int(parts[0][1:]); lid=f'umi-l{number:02}'
        lesson={'id':lid,'number':number,'volume':1 if number<=12 else 2,'titleRu':parts[1],'compatibility':{'textbook':'Genki','edition':3,'lesson':number},'wordIds':[],'rules':[],'exerciseIds':[]}
        lessons.append(lesson)
        for w in parts[2].split(';'):
            surface,reading,meaning=w.split(','); wid='word.'+reading
            if wid not in words: words[wid]={'id':wid,'surface':surface,'reading':reading,'meaningsRu':[meaning],'partOfSpeech':'expression','provenance':provenance}
            lesson['wordIds'].append(wid)
        continue
    title,rule,prompt,translation,opts=parts
    rid=f'{lid}.g{len(lesson["rules"])+1:02}'
    options=opts.split(';')
    lesson['rules'].append({'id':rid,'titleRu':title,'formationRu':rule,'example':prompt.replace('［］',options[0]),'translationRu':translation})
    exercise={'id':rid+'.gap','version':1,'status':'draft','type':'gap','focus':'grammar','lessonId':lid,'skillIds':[rid],'targetWordIds':[],'prerequisiteSkillIds':[], 'instructionRu':'Выбери вариант для заданного смысла и стиля.','prompt':[{'text':prompt.replace('［］','{{answer}}'),'reading':None}], 'translationRu':translation,'options':[{'id':f'o{i}','text':o,'feedbackRu':f'«{o}» '+('передаёт заданную форму и смысл.' if i==0 else 'не подходит к указанному смыслу, форме или способу построения. '+rule),'misconceptionId':None if i==0 else rid+'.form'} for i,o in enumerate(options)],'slots':[{'id':'answer','acceptedOptionIds':['o0']}],'acceptedChoiceIds':[],'acceptedSequences':[],'allowOptionReuse':False,'explanationRu':rule,'display':{'hideReadings':False},'provenance':provenance}
    exercises.append(exercise);lesson['exerciseIds'].append(exercise['id'])
# Independent sentence-assembly examples. Each task fixes the initial block to
# avoid rejecting alternate Japanese word orders without context.
